$_LANG['cloudSlider']['feature01Title'] = "Maximální dostupnost serverů";
$_LANG['cloudSlider']['feature01Description'] = "Dostupnost serverů je pro každou firmu zásadní – je to srdce hostingu vašeho podnikání. Souborové a databázové servery, e-mailové a webové servery jsou nepostradatelnou součástí většiny firemních procesů a výpadky mají přímý negativní dopad na produktivitu, prodeje i spokojenost zaměstnanců a zákazníků. Proto je pro nás maximální dostupnost serverů tak důležitá – chceme, aby vaše firemní procesy běžely bez problémů a vaši zákazníci byli spokojení.";
$_LANG['cloudSlider']['feature01DescriptionTwo'] = "Pokud nám svěříte potřeby své firmy, garantujeme vám dostupnost 99,9 % u všech poskytovaných služeb, s výjimkou běžné plánované údržby.";
$_LANG['cloudSlider']['feature02Title'] = "Celosvětové doručování dat";
$_LANG['cloudSlider']['feature02Description'] = "Naše služby běží na stovkách serverů v datových centrech po celém světě, takže se můžete spolehnout, že zákazníci se na váš web dostanou odkudkoli. Navíc poskytujeme monitorovací nástroje s odbornou analytikou – sledování návštěvnosti je důležitým krokem ke zlepšení efektivity a oblíbenosti webu i k přehledu o tom, odkud návštěvníci přicházejí, v jakou denní dobu web navštěvují a jak dlouho na něm zůstávají. Naše globální zaměření se týká i registrace domén – nabízíme registraci nejoblíbenějších TLD.";
$_LANG['cloudSlider']['feature02DescriptionTwo'] = "Naše zákaznická podpora je také k dispozici po celém světě. Rádi vám s hostingem pomůžeme všemi možnými způsoby – kontaktovat nás můžete telefonicky, e-mailem nebo přes live chat.";
$_LANG['cloudSlider']['feature03Title'] = "Špičkové zabezpečení";
$_LANG['cloudSlider']['feature03Description'] = "Můžete být v klidu – zajišťujeme nepřetržitý bezpečnostní monitoring a ochranu proti DDoS útokům. Ochranu dat svých zákazníků berete vážně a my také. Náš bezpečnostní tým a ochranná opatření pracují každý den 24 hodin denně, aby zajistily úroveň zabezpečení, jakou dnešní digitální doba vyžaduje.";
$_LANG['cloudSlider']['feature03DescriptionTwo'] = "K dispozici máte širokou škálu bezpečnostních nástrojů včetně SSL certifikátů, konfigurace firewallu, služeb bezpečnostního monitoringu, přístupu přes VPN a dalších.";
$_LANG['cloudSlider']['selectProductLevel'] = "Vyberte si úroveň, která vám přesně sedí!";
$_LANG['codeApplied'] = "Promo kód byl použit";

