$_LANG['store']['ssl']['dv']['tagline'] = "Zabezpečte svou webovou stránku během několika minut!";
$_LANG['store']['ssl']['dv']['descriptionTitle'] = "Co je Standardní DV SSL?";
$_LANG['store']['ssl']['dv']['descriptionContent'] = "<p>Certifikáty Domain Validation nabízejí ekonomický a rychlý způsob, jak implementovat SSL na vašem webu. Certifikáty ověřující doménu potvrzují vaše vlastnictví domény, ale neprovádějí žádné další ověření na úrovni organizace.</p><p>Certifikáty ověřující doménu jsou ideální pro osobní weby, blogy a sociální média nebo jakékoli stránky, které nepřenášejí soukromé a důvěrné informace. Certifikát ověřující doménu aktivuje zámek v prohlížeči a umožňuje použití https, což ujišťuje návštěvníky vašeho webu a zákazníky o vážném přístupu k jejich soukromí.</p>";

$_LANG['store']['ssl']['ov']['tagline'] = "Vysoká úroveň zabezpečení SSL ukazuje návštěvníkům webu vaši ověřenou identitu";
$_LANG['store']['ssl']['ov']['descriptionTitle'] = "Co je SSL s ověřením organizace?";
$_LANG['store']['ssl']['ov']['descriptionContent'] = "<p>SSL certifikáty s ověřením organizace poskytují okamžité potvrzení identity a silnou ochranu SSL pro váš web a podnikání.</p><p>OV SSL je certifikát ověřený organizací, který vašemu webu poskytuje větší důvěryhodnost než SSL certifikáty ověřující pouze doménu. Aktivuje zámek v prohlížeči a https, zobrazuje vaši firemní identitu a ujišťuje vaše zákazníky o vážném přístupu k zabezpečení. Návštěvníci webu mohou ověřit, že web provozuje legitimní společnost a není to podvodná stránka.</p>";

$_LANG['store']['ssl']['ev']['tagline'] = "Aktivujte zelenou adresní lištu pro nejvyšší důvěru a konverze";
$_LANG['store']['ssl']['ev']['descriptionTitle'] = "Co je SSL s rozšířeným ověřením?";
$_LANG['store']['ssl']['ev']['descriptionContent'] = "<p>EV SSL je certifikát s rozšířeným ověřením, nejvyšší třída SSL dostupná dnes, která vašemu webu poskytuje větší důvěryhodnost ve srovnání s použitím SSL certifikátu ověřeného organizací nebo doménou.</p><p>SSL s rozšířeným ověřením většinou zobrazuje název vaší společnosti nebo webu v zelené barvě. Toto výrazné vizuální ověření poskytuje návštěvníkům webu další jistotu, že byla podniknuta opatření k potvrzení identity webu a podnikání, které navštěvují, což zvyšuje důvěru uživatelů ve vaši webu a jeho důvěryhodnost - to je důvod, proč si většina velkých společností a organizací vybírá EV certifikáty.</p>";

$_LANG['store']['ssl']['wildcard']['tagline'] = "Zabezpečte neomezený počet subdomén na jednom certifikátu.";
$_LANG['store']['ssl']['wildcard']['descriptionTitle'] = "Co je Wildcard SSL certifikát?";
$_LANG['store']['ssl']['wildcard']['descriptionContent'] = "<p>Wildcard SSL umožňuje zabezpečit neomezený počet subdomén na jednom certifikátu. Je to skvělé řešení pro každého, kdo hostuje nebo spravuje více webů nebo stránek, které existují na téže doméně. Jednorázová cena certifikátu pokrývá další subdomény, které můžete v budoucnu přidat.</p><p>Na rozdíl od standardního SSL certifikátu, který je vydán pouze pro jednu plně kvalifikovanou doménovou jméno, například www.example.com, což znamená, že jej lze použít pouze pro přesnou doménu, pro kterou byl vydán, je Wildcard SSL certifikát vydán pro *.example.com, kde hvězdička představuje všechny možné subdomény.</p><p>Wildcard SSL je možnost dostupná pro DV a OV SSL certifikáty.</p>";

$_LANG['store']['websiteBuilder']['headline'] = "Vytvořit web nebylo nikdy snazší";
