$_LANG['store']['websiteBuilder']['introduction'] = "Nástroj Weebly pro tvorbu webu metodou drag & drop usnadňuje vytvoření výkonného a profesionálního webu bez technických znalostí. Více než 40 milionů podnikatelů a malých firem již Weebly použilo k vybudování své online prezentace v podobě webu, blogu nebo e-shopu.";

