$_LANG['ssl']['reissueSuccess'] = "Žádost o opětovné vydání byla úspěšně odeslána!";
$_LANG['ssl']['reissueSuccessInfo'] = "<p>Vaše žádost o opětovné vydání certifikátu byla odeslána certifikační autoritě.</p><p>Brzy obdržíte email na adresu <em>:approverEmail</em> s žádostí o schválení certifikátu.</p><p>Pokud email nedostanete, zkontrolujte prosím filtry spamu a složky s antivirovou ochranou, zda nebyl email karanténován. Pokud ho stále nemůžete najít, prosím <a href=\"submitticket.php\">kontaktujte podporu</a>.</p>";
$_LANG['ssl']['approverEmailUpdateSuccess'] = "Email pro schválení byl úspěšně aktualizován!";
$_LANG['ssl']['approverEmailUpdateInfo'] = "<p>Brzy obdržíte email na adresu <em>:newApproverEmail</em> s žádostí o schválení certifikátu.</p><p>Pokud email nedostanete, zkontrolujte prosím filtry spamu a složky s antivirovou ochranou, zda nebyl email karanténován. Pokud ho stále nemůžete najít, prosím <a href=\"submitticket.php\">kontaktujte podporu</a>.</p>";
