$_LANG['ssl']['approverEmailProcess'] = "<h4>O procesu schvalování emailem</h4><p>Pro vydání SSL certifikátu musí certifikační autorita ověřit autentičnost objednávky certifikátu, aby zajistila, že žádost je legitimní a pochází od autorizovaného vlastníka domény.</p><p>Ověření domény pomocí emailu je nejběžnějším mechanismem ověření certifikátu pro objednávky certifikátů. Certifikační autorita sestaví seznam schválených emailových adres pomocí běžných administrativních emailových adres (například admin nebo webmaster) v kombinaci s veřejnými WHOIS daty pro doménu. K potvrzení vlastnictví můžete použít pouze jednu z těchto emailových adres.</p>";



