$_LANG['store']['sitelock']['contentBodyParagraph1'] = "SiteLock&trade;, světový lídr v zabezpečení webů, chrání váš web, abyste mohli být v klidu.";
$_LANG['store']['sitelock']['contentBodyParagraph2'] = "Denní skenování malwaru SiteLock odhaluje zranitelnosti a známý škodlivý kód a automaticky je z webu odstraňuje, aby chránil váš web i návštěvníky před hrozbami.";
$_LANG['store']['sitelock']['contentBodyParagraph3'] = "Navíc získáte pečeť důvěryhodnosti SiteLock Trust Seal, která posiluje důvěru zákazníků a prokazatelně zvyšuje prodeje a míru konverze.";
$_LANG['store']['sitelock']['comparePlans'] = "Porovnat plány SiteLock";
