$_LANG['store']['sitelock']['featuresMalwareTitle'] = "Skenování malwaru";
$_LANG['store']['sitelock']['featuresMalwareContent'] = "Aktivně sleduje váš web a upozorní vás na jakýkoli zjištěný malware.";
