$_LANG['store']['sitelock']['featuresSetupTitle'] = "Rychlé automatické nastavení";
$_LANG['store']['sitelock']['featuresSetupContent'] = "Okamžité a plně automatizované nastavení vám poskytne ochranu ihned, bez nutnosti cokoli instalovat.";
$_LANG['store']['sitelock']['featuresCDNTitle'] = "Síť pro doručování obsahu (CDN)";
$_LANG['store']['sitelock']['featuresCDNContent'] = "Zrychlete svůj web jeho globální distribucí – návštěvníkům se načítá z nejbližšího místa, takže se stránky načítají rychleji, ať jsou kdekoli.";
$_LANG['store']['sitelock']['emergencyPlanTitle'] = "Byl váš web hacknut?";
$_LANG['store']['sitelock']['emergencyPlanHeadline'] = "Opravte to hned se SiteLock Emergency Response";
$_LANG['store']['sitelock']['emergencyPlanBody'] = "Pokud byl váš web napaden a kompromitován, získejte okamžitou nouzovou pomoc k jeho rychlé obnově. SiteLock Emergency Response vám pomůže takto:";
$_LANG['store']['sitelock']['emergencyPlanResponseTitle'] = "Okamžitá reakce";
$_LANG['store']['sitelock']['emergencyPlanResponseContent'] = "Získejte naši nejrychlejší odezvu – analýza a práce na obnově webu začnou do 30 minut.";
$_LANG['store']['sitelock']['emergencyPlanMalwareTitle'] = "Kompletní odstranění malwaru";
$_LANG['store']['sitelock']['emergencyPlanMalwareContent'] = "Pokud naše automatická technologie nedokáže škodlivý obsah odstranit, provedeme ruční vyčištění.";
$_LANG['store']['sitelock']['emergencyPlanPriorityTitle'] = "Prioritní vyřízení";
$_LANG['store']['sitelock']['emergencyPlanPriorityContent'] = "S nouzovým balíčkem se dostanete rovnou na začátek fronty.";
$_LANG['store']['sitelock']['emergencyPlanAftercareTitle'] = "7denní následná péče";
$_LANG['store']['sitelock']['emergencyPlanAftercareContent'] = "Track progress with our real-time updates throughout the process of cleaning and recovering your site.";
$_LANG['store']['sitelock']['emergencyPlanUpdatesTitle'] = "Informace v reálném čase";
$_LANG['store']['sitelock']['emergencyPlanUpdatesContent'] = "Sledujte průběh díky průběžným informacím v reálném čase během celého čištění a obnovy webu.";
$_LANG['store']['sitelock']['emergencyPlanPaymentTitle'] = "Jednorázová platba";
$_LANG['store']['sitelock']['emergencyPlanPaymentContent'] = "Nouzová služba je dostupná za jednorázový poplatek, bez opakovaných plateb či předplatného.";
$_LANG['store']['sitelock']['emergencyPlanOnlyCost'] = "Jen :price za 7 dní ochrany";
$_LANG['store']['sitelock']['buyNow'] = "Koupit nyní";
$_LANG['store']['sitelock']['faqTitle'] = "Často kladené dotazy";
$_LANG['store']['sitelock']['faqOneTitle'] = "Co je SiteLock?";
$_LANG['store']['sitelock']['faqOneBody'] = "SiteLock poskytuje jednoduché, rychlé a cenově dostupné zabezpečení webů všech velikostí. Společnost byla založena v roce 2008 a chrání více než 12 milionů webů po celém světě. Cloudová sada produktů SiteLock nabízí automatickou detekci zranitelností webu a odstraňování malwaru, ochranu proti DDoS, zrychlení webu, hodnocení rizik webu a soulad s PCI.";
$_LANG['store']['sitelock']['faqOneBodyLearnMore'] = "Chcete-li se o SiteLock dozvědět více, :learnMoreLink";
$_LANG['store']['sitelock']['faqOneBodyLearnLinkText'] = "klikněte sem a podívejte se na video „Jak SiteLock funguje“";
$_LANG['store']['sitelock']['faqTwoTitle'] = "Co SiteLock dělá?";
$_LANG['store']['sitelock']['faqTwoBody'] = "SiteLock poskytuje komplexní zabezpečení webu. Denně web skenuje a hledá zranitelnosti či malware. Pokud je najde, budete okamžitě upozorněni. V závislosti na vašem skeneru SiteLock automaticky odstraní z webu veškerý malware.  U webů s redakčním systémem (CMS) dokáže SiteLock nalezené zranitelnosti automaticky záplatovat.";
$_LANG['store']['sitelock']['faqThreeTitle'] = "Jaké typy problémů SiteLock vyhledává?";
$_LANG['store']['sitelock']['faqThreeBody'] = "SiteLock disponuje technologií pro komplexní skenování webu, které zahrnuje:";
$_LANG['store']['sitelock']['faqThreeBodyList1Title'] = "Skenování a odstraňování malwaru v souborech";
$_LANG['store']['sitelock']['faqThreeBodyList1'] = "SiteLock denně skenuje soubory webu na malware. Pokud je malware nalezen, vlastník webu je okamžitě upozorněn. SiteLock nabízí také komplexní skenování s automatickým odstraněním malwaru.";
$_LANG['store']['sitelock']['faqThreeBodyList2Title'] = "Skenování zranitelností";
$_LANG['store']['sitelock']['faqThreeBodyList2'] = "SiteLock skenuje webové aplikace na běžné zranitelnosti, které by mohly vést ke kompromitaci.";
$_LANG['store']['sitelock']['faqThreeBodyList3Title'] = "Zabezpečení aplikací a záplatování zranitelností";
$_LANG['store']['sitelock']['faqThreeBodyList3'] = "SiteLock disponuje technologií pro automatické záplatování zranitelností v redakčních systémech (CMS).";
$_LANG['store']['sitelock']['faqFourTitle'] = "Co jsou zranitelnosti a malware?";
$_LANG['store']['sitelock']['faqFourBodyParagraph1'] = ":vulnerabilityStrong je slabina nebo chybná konfigurace v kódu webu či webové aplikace, která útočníkovi umožní získat určitou kontrolu nad webem a případně i nad hostingovým serverem. Většina zranitelností je zneužívána automatizovaně, například pomocí skenerů zranitelností a botnetů.";
$_LANG['store']['sitelock']['websiteVulnerability'] = "zranitelnost webu";
$_LANG['store']['sitelock']['faqFourBodyParagraph2'] = ":malwareStrong. short for malicious software, is used to gather sensitive data, gain unauthorized access to websites and even hijack computers.";
$_LANG['store']['sitelock']['malware'] = "Malware";
$_LANG['store']['sitelock']['faqFiveTitle'] = "Ovlivní SiteLock výkon webu?";
$_LANG['store']['sitelock']['faqFiveBody'] = "Ne. Při skenování webu SiteLock stáhne příslušné soubory na zabezpečený server a skenuje je tam. Nemá to žádný vliv na obsah, kód, přenos dat ani serverové prostředky webu.";
$_LANG['store']['sitelock']['faqSixTitle'] = "Co je SiteLock Trust Seal?";
$_LANG['store']['sitelock']['faqSixBody'] = "SiteLock Trust Seal je široce uznávaný bezpečnostní odznak, který můžete zobrazit na svém webu. Jasně ukazuje, že je váš web bezpečný a bez malwaru. Pro přidání pečeti stačí vložit fragment kódu od SiteLock do patičky webu.";

