$_LANG['store']['ssl']['landingPage']['help']['ov']['compliance'] = "Splňuje požadavky prohlížečů";
$_LANG['store']['ssl']['landingPage']['help']['ov']['for'] = "Ideální pro citlivější stránky, například přihlašovací";
$_LANG['store']['ssl']['landingPage']['help']['ov']['type'] = "OV si představte jako získání řidičského průkazu – více překážek než u průkazky do knihovny, ale jako doklad totožnosti je důvěryhodnější.";
