$_LANG['store']['ssl']['landingPage']['help']['ev']['title'] = "Rozšířené ověření (EV)";
$_LANG['store']['ssl']['landingPage']['help']['ev']['verify'] = "Ověřování založené na standardech, představující nejvyšší úroveň ověření u SSL certifikátů";
$_LANG['store']['ssl']['landingPage']['help']['ev']['issued'] = "Obvykle vydán do 1–3 dnů";
$_LANG['store']['ssl']['landingPage']['help']['ev']['compliance'] = "Splňuje požadavky prohlížečů i dalších oborových standardů";
$_LANG['store']['ssl']['landingPage']['help']['ev']['for'] = "Ideální pro citlivé stránky včetně e-shopů, internetového bankovnictví a registrací účtů";
$_LANG['store']['ssl']['landingPage']['help']['ev']['type'] = "EV si představte jako vydání cestovního pasu – mnohem přísnější proces, delší lhůty a důkladnější ověření vaší identity než u průkazky do knihovny nebo řidičského průkazu. Mezinárodně uznáváno jako nejdůvěryhodnější způsob ověření identity.";
$_LANG['store']['ssl']['landingPage']['help']['ev']['browse'] = "Procházet certifikáty s rozšířeným ověřením";
$_LANG['store']['ssl']['landingPage']['viewAll'] = "Zobrazit všechny SSL certifikáty";
$_LANG['store']['ssl']['landingPage']['buyNow'] = "Koupit nyní";
$_LANG['store']['ssl']['landingPage']['faq']['title'] = "Časté dotazy";
$_LANG['store']['ssl']['landingPage']['geoTrust']['recommended'] = "Většina osobních a nekomerčních webů.";
$_LANG['store']['ssl']['landingPage']['geoTrust']['title'] = "Ochrana celého webu";
$_LANG['store']['ssl']['landingPage']['faq']['q1'] = "Co je SSL certifikát?";
$_LANG['store']['ssl']['landingPage']['faq']['a1'] = "SSL certifikáty umožňují šifrování dat na internetu a bezpečný přenos dat z webového serveru do prohlížeče. Díky SSL může váš web používat protokol https a v prohlížečích návštěvníků zobrazí zámek, který značí zabezpečené spojení.";
$_LANG['store']['ssl']['landingPage']['faq']['q2'] = "Proč potřebuji SSL certifikát?";
$_LANG['store']['ssl']['landingPage']['faq']['a2'] = "SSL certifikáty jsou nezbytnou součástí internetu. Nejen že šifrují komunikaci mezi vaším počítačem a serverem, na kterém je web umístěn, ale také ověřují, že web je skutečně tím, za co se vydává.";
$_LANG['store']['ssl']['landingPage']['faq']['q3'] = "Jaké jsou typy SSL?";
$_LANG['store']['ssl']['landingPage']['faq']['a3'] = "SSL certifikáty se dělí podle 3 úrovní ověření: ověření domény (DV), ověření organizace (OV) a rozšířené ověření (EV). Hlavní rozdíl mezi typy certifikátů spočívá v údajích, které certifikační autorita (RapidSSL, GeoTrust a DigiCert) vyžaduje a ověřuje před vydáním certifikátu. Vyšší úrovně certifikátů vyžadují více údajů, které se často zobrazují v adresním řádku prohlížeče. Například EV SSL zbarví adresní řádek zeleně a zobrazí návštěvníkům název organizace, což posiluje důvěru.";
$_LANG['store']['ssl']['landingPage']['faq']['q4'] = "Co je wildcard SSL certifikát?";
$_LANG['store']['ssl']['landingPage']['faq']['a4'] = "Wildcard SSL certifikát poskytuje stejné šifrování a ověření jako ostatní SSL certifikáty, ale lze jej navíc použít pro neomezený počet subdomén webu. Wildcard SSL certifikát pokrývá hlavní doménu (example.com) i její subdomény.";
$_LANG['store']['ssl']['landingPage']['faq']['q5'] = "Jaké výhody má EV SSL certifikát?";
$_LANG['store']['ssl']['landingPage']['faq']['a5'] = "Certifikáty EV (Extended Validation) jsou nejvyšší třídou SSL a dodávají vašemu webu největší věrohodnost a důvěru. EV zaručuje zákazníkům, že jejich osobní a finanční údaje jsou chráněny na nejvyšší úrovni ověření. Provádějí se dodatečné kontroly, například ověření v obchodním rejstříku, kontaktních údajů žadatele a toho, zda firma existuje alespoň 3 roky. Certifikáty EV jsou nejvhodnější pro stránky klíčové pro podnikání.";
$_LANG['store']['ssl']['landingPage']['faq']['q6'] = "Co když už SSL certifikát mám?";
$_LANG['store']['ssl']['landingPage']['faq']['a6'] = "Přejít k nám můžete kdykoli.  Nabízíme velmi konkurenceschopné ceny, a pokud již máte certifikát od konkurence, přičteme vám jeho zbývající platnost, maximálně však 12 měsíců navíc.";

