$_LANG['store']['socialbee']['content']['header'] = "Vyřiďte všechny úkoly na sociálních sítích z jednoho místa.";
$_LANG['store']['socialbee']['content']['p1'] = "Pokud své účty na sociálních sítích spravujete ručně, pravděpodobně trávíte hodiny přepínáním mezi platformami a záložkami.";
$_LANG['store']['socialbee']['content']['p2'] = "SocialBee vám to usnadní – příspěvky můžete vytvořit a naplánovat předem, takže vaše účty zůstanou aktivní, i když máte plné ruce práce nebo si dáváte pauzu. Publikování obstará za vás, ušetří vám starosti s ručním zveřejňováním a nabízí nástroje AI, které vám pomohou vytvořit obsah během chvilky.";
$_LANG['store']['socialbee']['content']['p3'] = "Můžete také odpovídat na komentáře, zmínky a zprávy, spolupracovat s týmem a sledovat výsledky, a to vše bez otevírání další záložky.";
$_LANG['store']['socialbee']['faq']['a1'] = "Můžete spravovat a plánovat obsah pro oblíbené platformy jako Facebook, Instagram, Threads, X™ (dříve Twitter™), LinkedIn, Pinterest, Google Business Profile™, TikTok, YouTube™ a Bluesky.";
$_LANG['store']['socialbee']['faq']['a2']['i1'] = "Komplexní nástroj pro správu sociálních sítí, který zvládne vše od tvorby, plánování a sdílení obsahu až po analytiku, sociální schránku a týmovou spolupráci.";
$_LANG['store']['socialbee']['faq']['a2']['i2'] = "Podporu prostřednictvím <a href='href=https://socialbee.com/calendar/'>hovorů</a>, chatu nebo e-mailu. Patříme mezi několik málo nástrojů pro sociální sítě, které stále nabízejí telefonickou podporu.";
$_LANG['store']['socialbee']['faq']['a2']['i3'] = "<a href='https://socialbee.com/webinars/'>Měsíční živé ukázky</a> práce se SocialBee, <a href='https://help.socialbee.com/'>podrobnou nápovědu</a>, <a href='https://www.youtube.com/@SocialBeeHQ'>krátké návody</a> a mnoho <a href='https://socialbee.com/resources/'>dalších materiálů o sociálních sítích</a>.";
$_LANG['store']['socialbee']['faq']['a2']['i4'] = "<a href='https://socialbee.com/roadmap/'>Transparentní plán vývoje</a> toho, co SocialBee chystá.";
$_LANG['store']['socialbee']['faq']['a2']['i5'] = "<a href='https://changelog.socialbee.com/'>Měsíční vydání nových funkcí</a>.";
$_LANG['store']['socialbee']['faq']['a2']['text'] = "Spolupráce se SocialBee vám přináší:";
$_LANG['store']['socialbee']['faq']['a3'] = "Uživatelé mohou získat pomoc od SocialBee prostřednictvím chatu, <a href='mailto:hello@socialbee.com'>e-mailu</a>, <a href='https://socialbee.com/calendar/'>hovorů</a> a <a href='https://help.socialbee.com/'>bohaté znalostní báze</a> plné užitečných materiálů.";
$_LANG['store']['socialbee']['faq']['a4']['text'] = "Agenturní plány (Pro50, Pro100 a Pro150) mají stejné funkce jako plán Pro. Hlavní rozdíly jsou v počtu sociálních profilů, které můžete připojit, v počtu pracovních prostorů a v počtu uživatelů, které můžete do pracovního prostoru přidat:";
