$_LANG['store']['socialbee']['features']['create']['i1'] = "SocialBee se integruje s Canva, Unsplash a GIPHY, takže můžete snadno vytvářet a vybírat vizuály pro své příspěvky.";
$_LANG['store']['socialbee']['features']['create']['i2'] = "Generujte popisky a obrázky během několika sekund pomocí AI a využijte více než 1 000 připravených promptů, které vám ušetří čas.";
$_LANG['store']['socialbee']['features']['create']['i3'] = "Přizpůsobte příspěvky každé platformě automaticky pomocí AI nebo ručně, aby váš obsah fungoval co nejlépe všude, kde je sdílen.";
$_LANG['store']['socialbee']['features']['create']['i4'] = "Nechte Copilot, AI asistenta SocialBee, aby vám během několika minut vytvořil personalizovaný obsahový plán. Už žádné hádání, co a kdy zveřejnit.";
$_LANG['store']['socialbee']['features']['create']['i5'] = "Uspořádejte příspěvky do složek podle témat, aby byl váš obsahový plán pestrý a dobře strukturovaný.";
$_LANG['store']['socialbee']['features']['create']['i6'] = "Experimentujte s různými typy příspěvků, jako jsou obrázky, videa, karusely, příběhy a Reels, a zjistěte, co vaše publikum nejvíce osloví.";
$_LANG['store']['socialbee']['features']['engage']['i1'] = "Odpovídejte na všechny komentáře, zmínky a soukromé zprávy ze sociálních sítí v jedné přehledné schránce.";
$_LANG['store']['socialbee']['features']['engage']['i2'] = "Ušetřete čas a mějte přehled o konverzacích, aniž byste museli přepínat mezi účty na sociálních sítích.";
$_LANG['store']['socialbee']['features']['engage']['i3'] = "Dostávejte upozornění, kdykoli někdo reaguje na váš obsah, abyste nepropásli důležité zprávy ani příležitosti k interakci.";
$_LANG['store']['socialbee']['features']['engage']['i4'] = "Komunikujte se sledujícími v reálném čase, budujte komunitu a odpovídejte na dotazy zákazníků pomocí rychlých odpovědí.";
$_LANG['store']['socialbee']['features']['engage']['i5'] = "Sledujte zmínky o své značce, abyste věděli, co o vás lidé říkají, a měli přehled o konverzacích a zpětné vazbě.";
$_LANG['store']['socialbee']['features']['engage']['i6'] = "Pomocí nástěnek a streamů si uspořádejte komentáře, zmínky a zprávy tak, aby se vám snadno spravovaly.";
$_LANG['store']['socialbee']['features']['schedule']['i1'] = "Plánujte příspěvky pro hlavní platformy jako Facebook®, Instagram, LinkedIn®, TikTok, Pinterest a další, vše z jednoho místa.";
$_LANG['store']['socialbee']['features']['schedule']['i2'] = "Uspořádejte příspěvky ve vizuálním kalendáři, který na první pohled ukazuje celou vaši strategii na sociálních sítích.";
$_LANG['store']['socialbee']['features']['schedule']['i3'] = "Plánujte a řaďte příspěvky do fronty předem, aby vaše účty zůstaly aktivní bez nutnosti ručního zveřejňování.";
