$_LANG['store']['threesixtymonitoring']['faq']['title'] = "Časté dotazy";
$_LANG['store']['threesixtymonitoring']['faq']['q1'] = "Co je monitoring webu?";
$_LANG['store']['threesixtymonitoring']['faq']['a1'] = "Monitoring webu testuje dostupnost, výkon a celkovou funkčnost webů. Ověřuje, že váš web běží a je dostupný pro návštěvníky. Výsledky monitoringu vám umožní vyřešit problémy s webem dříve, než ovlivní vaše podnikání.";
$_LANG['store']['threesixtymonitoring']['faq']['q2'] = "Jak funguje monitoring webu?";
$_LANG['store']['threesixtymonitoring']['faq']['a2'] = "Monitoring webu provádí testy vašeho webu v pravidelných intervalech (každou 1, 5 nebo 10 minut podle plánu). Tyto testy odhalují problémy s webem. Při zjištění problému 360 Monitoring odešle upozornění a zaznamená problém k pozdější analýze.";
$_LANG['store']['threesixtymonitoring']['faq']['q3'] = "Jak funguje monitoring výkonu?";
$_LANG['store']['threesixtymonitoring']['faq']['a3'] = "Nástroje a procesy monitoringu výkonu kontrolují, jak dobře systém běží, sledováním systémových prostředků, jako je využití CPU, spotřeba paměti, využití disku, výkon vstupů/výstupů (I/O) a dostupnost sítě. 360 Monitoring sleduje všechny tyto metriky, aby vše běželo hladce.";
$_LANG['store']['threesixtymonitoring']['faq']['q4'] = "Proč je monitoring výkonu důležitý?";
$_LANG['store']['threesixtymonitoring']['faq']['a4'] = "Monitoring výkonu je zásadní pro odhalení výkonnostních problémů dříve, než poškodí vaše podnikání. Zjištění o systémových prostředcích vám také umožní aktivně plánovat budoucí potřeby.";
$_LANG['store']['threesixtymonitoring']['faq']['q5'] = "Jak funguje monitoring SSL?";
$_LANG['store']['threesixtymonitoring']['faq']['a5'] = "Monitoring SSL vám umožní sledovat SSL certifikáty a včas plánovat jejich obnovu, čímž zajistí bezproblémovou správu certifikátů.";
$_LANG['store']['threesixtymonitoring']['faq']['q6'] = "Které lokality jsou pro monitoring podporovány?";
$_LANG['store']['threesixtymonitoring']['faq']['a6'] = "Monitorovat můžete odkudkoli na světě – monitorovací lokality jsou v Austrálii, Kanadě, Finsku, Francii, Německu, Japonsku, Mexiku, Nizozemsku, Švédsku, Velké Británii a USA.";
$_LANG['store']['threesixtymonitoring']['faq']['q7'] = "Jaké jazyky jsou podporovány?";
$_LANG['store']['threesixtymonitoring']['faq']['a7'] = "360 Monitoring podporuje angličtinu, němčinu, japonštinu, španělštinu, italštinu, brazilskou portugalštinu, francouzštinu a ruštinu.";
$_LANG['store']['threesixtymonitoring']['faq']['q8'] = "Mohu svůj plán navýšit?";
$_LANG['store']['threesixtymonitoring']['faq']['a8'] = "Ano, svůj plán můžete kdykoli navýšit.";
$_LANG['store']['threesixtymonitoring']['faq']['q9'] = "Jsou za upozornění nějaké poplatky navíc?";
$_LANG['store']['threesixtymonitoring']['faq']['a9'] = "Všechny placené plány umožňují neomezená vícekanálová upozornění. Někteří operátoři mohou účtovat dodatečné poplatky za data nebo SMS zprávy.";
$_LANG['store']['threesixtymonitoring']['faq']['q10'] = "Co je monitoring serveru?";
$_LANG['store']['threesixtymonitoring']['faq']['a10'] = "Monitoring serveru pravidelně kontroluje a sleduje stav vašeho serveru včetně CPU, doby načítání, síťových statistik, paměti, využití disku a dalších údajů, aby vám pomohl rychle najít a vyřešit problémy.";
$_LANG['store']['threesixtymonitoring']['faq']['q11'] = "Co je kontrola celého webu?";
$_LANG['store']['threesixtymonitoring']['faq']['a11'] = "Kontrola celého webu chrání vaši online prezentaci před chybami. Prochází celý web nebo e-shop a odhaluje nefunkční odkazy, poškozené obrázky, chyby JavaScriptu a mnoho dalších anomálií, čímž pomáhá předcházet problémům.";

