$_LANG['store']['emailServices']['benefits']['incoming']['title'] = "Filtrování příchozích e-mailů vám přináší všechny tyto výhody...";
$_LANG['store']['emailServices']['benefits']['incoming']['1'] = "Kompletní ochrana schránky za konkurenceschopné ceny";
$_LANG['store']['emailServices']['benefits']['incoming']['2'] = "Mimořádně přesné filtrování";
$_LANG['store']['emailServices']['benefits']['incoming']['3'] = "Snadná konfigurace";
$_LANG['store']['emailServices']['benefits']['incoming']['4'] = "Vyšší kontinuita a redundance příchozí pošty";
$_LANG['store']['emailServices']['benefits']['incoming']['5'] = "Různé možnosti reportů";
$_LANG['store']['emailServices']['benefits']['incoming']['6'] = "Přívětivé rozhraní, díky kterému máte e-mail plně pod kontrolou";
$_LANG['store']['emailServices']['benefits']['incoming']['7'] = "Vyšší produktivita zaměstnanců";
$_LANG['store']['emailServices']['benefits']['incoming']['8'] = "Kompatibilní s jakýmkoli poštovním serverem";
$_LANG['store']['emailServices']['benefits']['incoming']['q1'] = "Proč zvolit filtr příchozí pošty SpamExperts?";
$_LANG['store']['emailServices']['benefits']['incoming']['a1'] = "Filtrování příchozích e-mailů prověřuje veškerou příchozí poštu a s téměř 100% přesností odstraňuje spam a viry dříve, než se dostanou do vaší sítě. Rozsáhlý ovládací panel vám ponechává plnou kontrolu. Pokud navíc váš poštovní server nefunguje, e-maily se uloží do fronty. K poště ve frontě máte přístup přes webové rozhraní, kde ji můžete číst i na ni odpovídat, což zvyšuje kontinuitu příchozí pošty!";
$_LANG['store']['emailServices']['benefits']['incoming']['q2'] = "Proč potřebujete profesionální filtr příchozí pošty?";
$_LANG['store']['emailServices']['benefits']['incoming']['a2'] = "Přestaňte riskovat hrozby pro vaši IT síť. Pokud je vaše schránka každý den zahlcená nevyžádanou hromadnou poštou, je to znamení, že potřebujete profesionální řešení filtrování příchozí pošty. Získejte plnou ochranu schránky a rozlučte se se spamem, viry a malwarem!";
$_LANG['store']['emailServices']['benefits']['incoming']['q3'] = "Jak to funguje";
$_LANG['store']['emailServices']['benefits']['incoming']['a3'] = "Jakmile je vaše doména (automaticky) nasazena do filtru příchozí pošty a filtrování je aktivováno, e-maily procházejí filtrovacím cloudem SpamExperts. Příchozí e-maily jsou bezpečně analyzovány a skenovány v reálném čase. Není potřeba žádné zaškolení ani konfigurace, vše funguje okamžitě. Zprávy rozpoznané jako spam se přesunou do karantény, ostatní pošta se odešle na váš poštovní server. Karanténu můžete sledovat v přehledném SpamPanelu, prostřednictvím e-mailových reportů nebo přímo ve svém e-mailovém klientovi! Už žádný ztracený čas se spamem – soustřeďte se na svou práci a mějte vše pod kontrolou.";
$_LANG['store']['emailServices']['benefits']['outgoing']['title'] = "Filtrování odchozích e-mailů vám přináší všechny tyto výhody...";
$_LANG['store']['emailServices']['benefits']['outgoing']['1'] = "Konec zařazování na blacklisty";
$_LANG['store']['emailServices']['benefits']['outgoing']['2'] = "Ochrana reputace vaší značky a IT systémů";
$_LANG['store']['emailServices']['benefits']['outgoing']['3'] = "Žádné náklady na vyřazení z blacklistů";
$_LANG['store']['emailServices']['benefits']['outgoing']['4'] = "Vyšší kontinuita a doručitelnost odchozí pošty";
$_LANG['store']['emailServices']['benefits']['outgoing']['5'] = "Vyšší produktivita zaměstnanců";
$_LANG['store']['emailServices']['benefits']['outgoing']['6'] = "Snazší řešení zneužití";
$_LANG['store']['emailServices']['benefits']['outgoing']['q1'] = "Co je filtrování odchozí pošty?";
$_LANG['store']['emailServices']['benefits']['outgoing']['a1'] = "Filtrování odchozích e-mailů je zásadní pro ochranu reputace vaší IT infrastruktury a zajištění, že veškerá odchozí pošta bezpečně dorazí tam, kam má. Toto profesionální řešení zablokuje spam a viry, aby neopustily vaši síť, a zabrání tomu, aby se vaše IP adresy kdy znovu ocitly na blacklistu. Filtr odchozí pošty SpamExperts vám navíc poskytuje reporty a nástroje k odhalení napadených účtů a zablokování uživatelů rozesílajících spam.";
$_LANG['store']['emailServices']['benefits']['outgoing']['q2'] = "Proč ho potřebujete?";
$_LANG['store']['emailServices']['benefits']['outgoing']['a2'] = "Odeslala už vaše síť spam bez vašeho vědomí? Kvůli slabinám sítě může být napadeno téměř jakékoli zařízení a zneužito k odesílání odchozí SMTP pošty, takže z vaší sítě může odcházet spam nebo malware, aniž byste o tom věděli! Proto je zásadní investovat do profesionálního řešení filtrování odchozí pošty. Udržte si dobrou pověst firmy, zastavte odchod spamu z vaší sítě a předejděte zařazení na blacklist, aby vaše e-maily vždy dorazily tam, kam mají.";
$_LANG['store']['emailServices']['benefits']['archiving']['title'] = "Archivace e-mailů vám přináší všechny tyto výhody...";
$_LANG['store']['emailServices']['benefits']['archiving']['1'] = "Včetně filtrování příchozích i odchozích e-mailů!";
$_LANG['store']['emailServices']['benefits']['archiving']['2'] = "Už nikdy nepřijdete o žádný e-mail!";
$_LANG['store']['emailServices']['benefits']['archiving']['3'] = "Splnění zákonných požadavků";
$_LANG['store']['emailServices']['benefits']['archiving']['4'] = "Vyšší výkon IT systémů";
$_LANG['store']['emailServices']['benefits']['archiving']['5'] = "Uživatelsky přívětivá správa ochrany dat";
$_LANG['store']['emailServices']['benefits']['archiving']['6'] = "Kontinuita e-mailu, podpora žurnálování a snadné opětovné doručení";
$_LANG['store']['emailServices']['benefits']['archiving']['7'] = "Komprimovaný, šifrovaný a bezpečný archiv";
$_LANG['store']['emailServices']['benefits']['archiving']['q1'] = "Archivace e-mailů";
$_LANG['store']['emailServices']['benefits']['archiving']['a1'] = "Archivace e-mailů uchovává a chrání všechny příchozí i odchozí e-maily pro pozdější přístup. Je to skvělý způsob, jak obnovit ztracené nebo omylem smazané e-maily, urychlit reakci při auditu, zabezpečit e-maily a přílohy s duševním vlastnictvím a využít je pro účely „eDiscovery“ v případě soudního sporu.";
$_LANG['store']['emailServices']['benefits']['archiving']['q2'] = "Proč ji potřebujete";
$_LANG['store']['emailServices']['benefits']['archiving']['a2a'] = "Zoufale hledáte důležitý e-mail z loňského roku, nemůžete jej najít a hrozí vám kvůli tomu pokuta nebo ztráta důležitého obchodu? Předejděte tomu profesionálním řešením archivace e-mailů. Archivace e-mailů je klíčovým nástrojem pro bezpečnou zálohu veškeré pošty a splnění zákonných požadavků.";
$_LANG['store']['emailServices']['benefits']['archiving']['a2b'] = "Zároveň platí, že e-mailová komunikace má právní váhu a je právně závazná, proto se dodržování předpisů v oblasti e-mailu stalo pro organizace mimořádně důležitým tématem. V některých odvětvích je proto povinné uchovávat bezpečnou zálohu všech e-mailových zpráv a plnit zákonné požadavky.";
