$_LANG['store']['ox']['standout']['feature1']['bullet1'] = "Profesionální email@vase-domena.cz";
$_LANG['store']['ox']['standout']['feature1']['bullet2'] = "Bezpečný a spolehlivý, s dostupností 99,9 %";
$_LANG['store']['ox']['standout']['feature1']['bullet3'] = "Používejte webmail, mobilní nebo desktopové aplikace";
$_LANG['store']['ox']['standout']['feature1']['bullet4'] = "Obrovské schránky 10 GB a 50 GB";
$_LANG['store']['ox']['standout']['feature2']['detail'] = "Pomocí AI a prediktivní ochrany e-mailu bojuje OX App Suite za bezpečí vaší schránky před spamem, viry, malwarem a phishingovými útoky.";
$_LANG['store']['ox']['standout']['feature3']['detail'] = "OX App Suite se synchronizuje napříč všemi vašimi zařízeními. Přístup z mobilu i počítače není problém, protože OX App Suite bez potíží funguje se všemi nativními klienty.";
$_LANG['store']['ox']['featuresHeadline'] = "Funkce";
$_LANG['store']['ox']['feature1']['title'] = "Cloudové úložiště souborů";
$_LANG['store']['ox']['feature1']['detail'] = "Ukládejte a sdílejte důležité dokumenty bezpečně v cloudu. S kapacitou až 50 GB budete mít dostatek místa na roky dopředu.";
$_LANG['store']['ox']['feature2']['title'] = "Kalendáře a kontakty";
$_LANG['store']['ox']['feature2']['detail'] = "Komunikujte jako velká firma – se sdílenými kalendáři, průvodcem plánováním schůzek, podporou iCal a globálním adresářem!";
$_LANG['store']['ox']['feature3']['title'] = "Spousta e-mailových funkcí";
$_LANG['store']['ox']['feature3']['detail'] = "Najdete zde všechny oblíbené e-mailové funkce včetně přesměrování, aliasů, automatických odpovědí, filtrů, podpisů, oznámení a dalších!";
$_LANG['store']['ox']['feature4']['title'] = "Přidejte kancelářské aplikace!";
$_LANG['store']['ox']['feature4']['detail'] = "Vytvářejte, upravujte a sdílejte dokumenty Microsoft Office jako Word, Excel a PowerPoint pomocí výkonných online aplikací App Suite.";
$_LANG['store']['ox']['feature5']['title'] = "Přineste si své aplikace";
$_LANG['store']['ox']['feature5']['detail'] = "Snadno připojte do App Suite své oblíbené e-mailové služby a aplikace, jako jsou Gmail, Dropbox, Zoom (již brzy) a další!";
$_LANG['store']['ox']['feature6']['title'] = "Na soukromí záleží";
$_LANG['store']['ox']['feature6']['detail'] = "App Suite ani my nikdy nebudeme číst, skenovat ani sdílet vaše osobní údaje či e-maily s žádnými třetími stranami. Nikdy.";
$_LANG['store']['ox']['pricingHeadline'] = "Ceny a plány";
$_LANG['store']['ox']['faq1']['question'] = "Jaké aplikace OX App Suite obsahuje?";
$_LANG['store']['ox']['faq1']['answer'] = "Všechny plány OX App Suite zahrnují přístup k webmailu, kalendáři, úkolům a adresáři. Balíček Productivity navíc přidává OX Drive a OX Documents (text, tabulky a prezentace).";
$_LANG['store']['ox']['faq2']['question'] = "Mohu do OX App Suite přidat externí e-mailové účty?";
$_LANG['store']['ox']['faq2']['answer'] = "Ano, OX App Suite podporuje připojení všech externích e-mailových účtů IMAP včetně oblíbených poskytovatelů, jako jsou Gmail, Yahoo a Outlook.com. Stačí do App Suite zadat svou e-mailovou adresu a heslo a veškerá pošta zaslaná na tyto účty se zobrazí v rozhraní App Suite.";
$_LANG['store']['ox']['faq3']['question'] = "Mohu synchronizovat kalendář a kontakty mezi OX App Suite a mobilním zařízením?";
$_LANG['store']['ox']['faq3']['answer'] = "Ano, OX App Suite plně podporuje CalDAV a CardDAV. Uživatelé Androidu mohou snadno synchronizovat pomocí naší aplikace Android Sync.";
$_LANG['store']['ox']['faq4']['question'] = "Bude OX App Suite fungovat na mém zařízení?";
$_LANG['store']['ox']['faq4']['answer'] = "App Suite bez problémů funguje s většinou nativních desktopových i mobilních e-mailových klientů.";
$_LANG['store']['ox']['faq4']['devices'] = "Mobilní zařízení: iPhone se systémem iOS 11/iOS 12, chytrý telefon se systémem Android 4.1 nebo novějším<br>Podporované prohlížeče: Safari, Chrome (aktuální a předchozí verze), Mozilla Firefox (aktuální a předchozí verze), Microsoft Internet Explorer 11/Edge";
$_LANG['store']['ox']['faq5']['question'] = "Chrání OX App Suite před spamem a viry?";
$_LANG['store']['ox']['faq5']['answer'] = "Ano! OX App Suite využívá vlastní technologii i partnerství se zavedenými dodavateli v oblasti ochrany proti spamu, aby byla vaše schránka co nejčistší a nejbezpečnější.";
$_LANG['store']['ox']['faq6']['question'] = "Co je OX Drive (Productivity)?";
$_LANG['store']['ox']['faq6']['answer'] = "OX Drive je online úložiště pro ukládání dokumentů, fotografií a médií v cloudu. Stačí vám tedy přístup k OX App Suite a OX Drive a máte k dispozici i všechny své soubory. OX Drive umožňuje synchronizovat soubory se všemi vašimi zařízeními pomocí prohlížeče nebo nativních aplikací.";
$_LANG['store']['ox']['faq7']['question'] = "Co je OX Documents (Productivity)?";
$_LANG['store']['ox']['faq7']['answer'] = "OX Text, OX Spreadsheet a OX Presentation jsou 3 aplikace, které souhrnně tvoří OX Documents. Slouží k online vytváření a úpravám textových dokumentů, tabulek a prezentací. Vytvářejte a upravujte dokumenty odkudkoli, se známými funkcemi kancelářského balíku a na všech svých zařízeních.";
$_LANG['store']['ox']['faq8']['question'] = "Jaké jazyky OX App Suite podporuje?";
$_LANG['store']['ox']['faq8']['answer'] = "OX App Suite supports the following languages: English, German, Spanish, French, Italian, Dutch, Polish, 中文 简体, 中文 繁體, 日本語 日本";
$_LANG['store']['ox']['faq9']['question'] = "Mohu převést svůj stávající e-mailový účet od jiného poskytovatele?";
$_LANG['store']['ox']['faq9']['answer'] = "Ano, nabízíme samoobslužný migrační nástroj, který je intuitivní a snadno použitelný. Migrujte ze všech oblíbených e-mailových služeb včetně Apple iCloud, Gmail, Outlook.com/Windows Live/Hotmail, Yahoo Mail, GMX nebo T-Online, případně ručně zadejte údaje svého poskytovatele pomocí IMAP/POP3 či jiných dostupných protokolů.";
