$_LANG['store']['addon']['wptk']['title'] = "WP Toolkit";
$_LANG['store']['addon']['wptk']['pleskTitle'] = "Smart Updates pro WordPress";
$_LANG['store']['addon']['wptk']['pleskTagline'] = "Posuňte práci s WordPressem na novou úroveň";
$_LANG['store']['addon']['wptk']['getItNow'] = "Pořídit nyní";
$_LANG['store']['addon']['wptk']['redefined1'] = "Správa WordPressu v novém pojetí s";
$_LANG['store']['addon']['wptk']['redefined2'] = "WP Toolkit Deluxe pro";
$_LANG['store']['addon']['wptk']['switchCpanel'] = "Hledáte WP Toolkit pro cPanel?";
$_LANG['store']['addon']['wptk']['switchPlesk'] = "Hledáte WP Toolkit pro Plesk?";
$_LANG['store']['addon']['wptk']['introTitle'] = "WP Toolkit Deluxe přináší výkonnou správu pluginů a šablon WordPressu, zabezpečení, automatizaci, klonování i zálohování a obnovu – vše v jednom přehledném rozhraní.";
$_LANG['store']['addon']['wptk']['introBody'] = "Zbavte se dohadů i zbytečné práce se správou WordPressu. Kromě všeho, co byste čekali – od snadného zálohování a obnovy přes správu indexace ve vyhledávačích až po přihlášení do WordPressu jedním kliknutím – získáte také automatické Smart Updates, staging a klonování pro snadné duplikování a testování webů, zabezpečení jedním kliknutím a mnoho dalšího!";
$_LANG['store']['addon']['wptk']['pleskIntroTitle'] = "Smart Updates pro WP Toolkit vyhledá a analyzuje dostupné aktualizace vašich instalací WordPressu a poté aktualizaci provede bez rizika pro ostrý web, nebo vás upozorní, že je k dispozici potenciálně nebezpečná aktualizace.";
$_LANG['store']['addon']['wptk']['pleskIntroBody'] = "Díky špičkové inteligenci a automatizaci udržuje Smart Updates vaše weby na WordPressu aktuální, online a chráněné před potenciálně škodlivými aktualizacemi jádra, pluginů a šablon.";
$_LANG['store']['addon']['wptk']['midTitle1'] = "Jediný toolkit, který :breaktag kdy budete potřebovat...";
$_LANG['store']['addon']['wptk']['featureTitle1'] = "Tvořte rychle a snadno";
$_LANG['store']['addon']['wptk']['featureBody1'] = "Instalujte a konfigurujte pluginy a šablony a upravte vzhled jednoho nebo všech svých webů na WordPressu najednou, jen několika kliknutími.";
$_LANG['store']['addon']['wptk']['featureTitle2'] = "Experimentujte bezpečně";
$_LANG['store']['addon']['wptk']['featureBody2'] = "Naklonujte libovolný existující web na WordPressu a testujte design, pluginy či cokoli jiného. Změny pak kdykoli synchronizujte zpět na ostrý web.";
$_LANG['store']['addon']['wptk']['featureTitle3'] = "Užívejte si bezpečí";
$_LANG['store']['addon']['wptk']['featureBody3'] = "Jediným kliknutím prověříte a zabezpečíte své weby na WordPressu proti vybraným bezpečnostním rizikům. Konkrétní weby nebo stránky můžete také chránit heslem.";
$_LANG['store']['addon']['wptk']['featureTitle4'] = "Automatizujte aktualizace";
$_LANG['store']['addon']['wptk']['featureBody4'] = "Smart Updates automaticky vyhledá a analyzuje aktualizace z hlediska kompatibility a bezpečnosti a poté je nainstaluje, nebo vás upozorní na problém. Váš web tak zůstane v bezpečí.";
$_LANG['store']['addon']['wptk']['featureTitle5'] = "Klonování a hromadné zabezpečení";
$_LANG['store']['addon']['wptk']['featureBody5'] = "Vytvořte si kopii ostrého webu pro experimenty a zároveň jediným kliknutím zabezpečte všechny své weby na WordPressu.";
$_LANG['store']['addon']['wptk']['featureTitle6'] = "Režim údržby";
$_LANG['store']['addon']['wptk']['featureBody6'] = "Dočasně vypněte web a zobrazte vlastní zprávu.";
$_LANG['store']['addon']['wptk']['smartUpdates']['featureTitle1'] = "Jak to funguje?";
$_LANG['store']['addon']['wptk']['smartUpdates']['featureBody1'] = "Smart Updates naklonuje a aktualizuje kopii ostrého webu a poté obě verze porovná, aby ověřil úspěšnost.";
$_LANG['store']['addon']['wptk']['smartUpdates']['featureTitle2'] = "Co když je aktualizace bezpečná?";
$_LANG['store']['addon']['wptk']['smartUpdates']['featureBody2'] = "Bezpečné aktualizace lze automaticky nainstalovat na ostrý web bez rizika jeho poškození.";
$_LANG['store']['addon']['wptk']['smartUpdates']['featureTitle3'] = "Co když aktualizace bezpečná není?";
$_LANG['store']['addon']['wptk']['smartUpdates']['featureBody3'] = "Vlastník webu uvidí rozhraní, kde může každý zjištěný problém posoudit a rozhodnout, zda chce pokračovat.";
$_LANG['store']['addon']['wptk']['plesk']['featureTitle1'] = "WordPress jednoduše";
$_LANG['store']['addon']['wptk']['plesk']['featureBody1'] = "Instalátor na jedno kliknutí zprovozní a nastaví WordPress od začátku do konce. Jeden přehled pro hromadnou správu více instalací WordPressu.";
$_LANG['store']['addon']['wptk']['plesk']['featureTitle2'] = "Staging a testování";
$_LANG['store']['addon']['wptk']['plesk']['featureBody2'] = "Testujte nové funkce a nápady v izolovaném prostředí, než je nasadíte do produkce – bez pluginů a bez samostatného serveru.";
$_LANG['store']['addon']['wptk']['plesk']['featureTitle3'] = "Ochrana proti útokům";
$_LANG['store']['addon']['wptk']['plesk']['featureBody3'] = "Web je ve výchozím stavu zabezpečený a ochranu dále posiluje bezpečnostní skener WP Toolkit. Nepotřebujete žádné znalosti zabezpečení.";
$_LANG['store']['addon']['wptk']['plesk']['featureTitle4'] = "Provoz a automatizace";
$_LANG['store']['addon']['wptk']['plesk']['featureBody4'] = "Spouštějte aktualizace WordPressu, šablon a pluginů jednotlivě nebo hromadně. Sledujte a spravujte všechny své weby na WordPressu z jednoho přehledu.";
$_LANG['store']['addon']['wptk']['plesk']['featureTitle5'] = "Bez zbytečné složitosti";
$_LANG['store']['addon']['wptk']['plesk']['featureBody5'] = "Staging, klonování, synchronizace, aktualizace, migrace a další složité úkoly jedním kliknutím. Žádné vystresované vývojářské týmy, žádné rizikové operace.";
$_LANG['store']['addon']['wptk']['plesk']['featureTitle6'] = "Jednoduché, ale ne amatérské";
$_LANG['store']['addon']['wptk']['plesk']['featureBody6'] = "Získejte plnou kontrolu díky WP-CLI, režimu údržby, správě ladění, správě indexace ve vyhledávačích a dalším funkcím.";
$_LANG['store']['addon']['wptk']['midTitle2'] = "Nejkomplexnější, nejbezpečnější a nejuniverzálnější toolkit pro WordPress";
$_LANG['store']['addon']['wptk']['screenshotDesc'] = "WP Toolkit Deluxe nabízí vše potřebné k instalaci, konfiguraci, aktualizaci a zabezpečení webů na WordPressu. Přejděte na WP Toolkit Deluxe ještě dnes již od :price.";
$_LANG['store']['addon']['wptk']['screenshotDescFree'] = "WP Toolkit Deluxe nabízí vše potřebné k instalaci, konfiguraci, aktualizaci a zabezpečení webů na WordPressu. Přejděte na WP Toolkit Deluxe ještě dnes.";
$_LANG['store']['addon']['wptk']['smartUpdates']['screenshotDesc'] = "Smart Updates pro WP Toolkit nabízí vše potřebné k tomu, aby vaše weby na WordPressu byly aktuální a běžely bez problémů. Přejděte na Smart Updates ještě dnes již od :price.";
$_LANG['store']['addon']['wptk']['smartUpdates']['screenshotDescFree'] = "Smart Updates pro WP Toolkit nabízí vše potřebné k tomu, aby vaše weby na WordPressu byly aktuální a běžely bez problémů. Přejděte na Smart Updates ještě dnes.";
