$_LANG['store']['siteBuilder']['title'] = "Site Builder";
$_LANG['store']['siteBuilder']['introHeadline'] = "Vaše cesta online <br class=\"hidden-xs\">začíná zde.";
$_LANG['store']['siteBuilder']['intro1'] = "Vytvoření online prezentace vyžaduje správnou platformu. Zviditelněte se s naším nástrojem pro tvorbu webu metodou drag & drop.";
$_LANG['store']['siteBuilder']['intro2'] = "Ať chcete propagovat sebe nebo svou firmu, náš nástroj pro tvorbu webu je založen na šablonách a průvodci s návodným obsahem – dostatečně jednoduchý pro začátečníky a bohatý na funkce pro profesionály. Působí jako PowerPoint, ale s větší silou, elegancí a jednoduchostí. Řešení, které vás bude bavit používat.";
$_LANG['store']['siteBuilder']['featuresTitle'] = "Funkce nástroje pro tvorbu webu";
$_LANG['store']['siteBuilder']['featuresEssentials'] = "Základy";
$_LANG['store']['siteBuilder']['featuresSocial'] = "Sociální sítě a blog";
$_LANG['store']['siteBuilder']['featuresStore'] = "Online obchod";
$_LANG['store']['siteBuilder']['features']['essentials']['tagline'] = "Náš nástroj pro tvorbu webu obsahuje kompletní sadu funkcí.";
$_LANG['store']['siteBuilder']['features']['blog']['tagline'] = "Sdílení vašeho příběhu dělá velký rozdíl. Spojte se s návštěvníky prostřednictvím sociálních sítí a svého blogu.";
$_LANG['store']['siteBuilder']['features']['store']['tagline'] = "Online prodej může nastartovat vaše podnikání. Vytvořte si web jako obchod, butik nebo e-shop.";
$_LANG['store']['siteBuilder']['features']['essentials']['1'] = "Editor drag & drop";
$_LANG['store']['siteBuilder']['features']['essentials']['2'] = "Funkce pro tvorbu";
$_LANG['store']['siteBuilder']['features']['essentials']['3'] = "Předem navržené stavební bloky";
$_LANG['store']['siteBuilder']['features']['essentials']['4'] = "Vestavěná optimalizace pro mobily";
$_LANG['store']['siteBuilder']['features']['essentials']['5'] = "Integrace fotobanky";
$_LANG['store']['siteBuilder']['features']['essentials']['6'] = "Automatické ukládání a zálohování";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['1'] = "Editor drag & drop umožňuje přidávat a uspořádávat prvky webu přímo na stránce se zvýrazněním vhodných míst pro umístění.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['2'] = "Použijte hotové prvky rozvržení, jako jsou texty, tlačítka, fotografie nebo ikony, a vytvořte libovolné profesionálně vypadající rozvržení webu.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['3'] = "Nemusíte ztrácet čas úpravami rozvržení obsahu. Kolekce více než 350 obsahových bloků vám pomůže vytvořit profesionální web bez technických znalostí.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['4'] = "Weby budou skvěle vypadat na jakémkoli zařízení. Šablony jsou 100% responzivní pro všechna zařízení včetně chytrých telefonů, tabletů a počítačů.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['5'] = "Obohaťte svůj web výběrem z více než 200 000 profesionálních prémiových fotografií ve vysokém rozlišení. Náš nástroj pro tvorbu webu zahrnuje také vkládání videí a optimalizaci obrázků.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['essentials']['6'] = "Díky ukládání v reálném čase nepřijdete o žádnou práci. Editor vše automaticky ukládá, zatímco pracujete.";
$_LANG['store']['siteBuilder']['features']['blog']['1'] = "Stránka blogu";
$_LANG['store']['siteBuilder']['features']['blog']['2'] = "Koncept příspěvku";
$_LANG['store']['siteBuilder']['features']['blog']['3'] = "Editor příspěvků";
$_LANG['store']['siteBuilder']['features']['blog']['4'] = "Sdílení na sociálních sítích";
$_LANG['store']['siteBuilder']['features']['blog']['5'] = "Komentáře a lajky z Facebooku";
$_LANG['store']['siteBuilder']['features']['blog']['6'] = "Propojení s Instagramem a Twitterem";
$_LANG['store']['siteBuilder']['featuresdescriptions']['blog']['1'] = "Sdílejte svůj příběh a spojte se s návštěvníky přidáním přizpůsobitelného blogu na web. Nastavte vzhled příspěvků na publikovaném webu.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['blog']['2'] = "Vytvořte příspěvek na blog hned a uložte jej k pozdějšímu zveřejnění, aby se shodoval s konkrétní novinkou nebo speciální akcí.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['blog']['3'] = "Upravujte příspěvky na blogu i po jejich zveřejnění pomocí vestavěného nástroje a editoru obsahu.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['blog']['4'] = "Povzbuďte návštěvníky, aby váš obsah lajkovali a sdíleli – přidejte na web ikony sociálních sítí, jako jsou Facebook, Twitter, LinkedIn a Pinterest.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['blog']['5'] = "Umožněte návštěvníkům komentovat a lajkovat vaši propojenou facebookovou stránku, aniž by opustili váš web.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['blog']['6'] = "Automaticky zobrazujte své fotografie z Instagramu na webu při každém novém příspěvku a informujte návštěvníky živým kanálem svého účtu na Twitteru.";
$_LANG['store']['siteBuilder']['features']['store']['1'] = "Flexibilní plány";
$_LANG['store']['siteBuilder']['features']['store']['2'] = "Bezpečné platby z celého světa";
$_LANG['store']['siteBuilder']['features']['store']['3'] = "Snadná a rychlá pokladna";
$_LANG['store']['siteBuilder']['features']['store']['5'] = "Výpis a správa produktů";
$_LANG['store']['siteBuilder']['features']['store']['6'] = "Akce, slevy a kupóny";
$_LANG['store']['siteBuilder']['features']['store']['7'] = "Správa skladu";
$_LANG['store']['siteBuilder']['features']['store']['8'] = "Doprava do celého světa";
$_LANG['store']['siteBuilder']['features']['store']['9'] = "Daně a DPH";
$_LANG['store']['siteBuilder']['features']['store']['10'] = "Správa a sledování objednávek";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['1'] = "Ať jste butik, obchod nebo velký e-shop, k dispozici jsou plány pro 10, 50 a 500 produktů.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['2'] = "Propojte se s PayPal, Square, Stripe a více než 50 důvěryhodnými poskytovateli plateb kartou a okamžitě přijímejte platební karty.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['3'] = "Nabídněte zákazníkům rychlejší a snazší dokončení objednávky s volitelnou registrací. Poskytněte bezpečnou jednostránkovou pokladnu včetně poznámek zákazníka k objednávce.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['5'] = "Vybírejte z několika rozvržení produktových stránek a upravte popisy i design podle svých představ. Usnadněte zákazníkům hledání produktů jejich rozdělením do kategorií.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['6'] = "Vytvářejte slevové kupóny nebo promo kódy a zvyšte prodeje. Zvyšte konverze zobrazením běžné ceny vedle zlevněné.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['7'] = "Sledování skladu pomáhá zjistit, kdy je čas doplnit zásoby produktu a které varianty produktu jsou nejoblíbenější.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['8'] = "Propojením e-shopu s přepravní společností, jako jsou USPS, FedEx, UPS, Australia Post, Canada Post apod., můžete zákazníkům v pokladně nabídnout aktuální ceny dopravy.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['9'] = "Nastavte výpočet daní pro libovolnou zemi nebo definujte konkrétní zóny. Mějte výpočet daní plně pod kontrolou – nastavte daně podle lokality, přidejte daň pro skupinu produktů nebo nastavte produkty bez daně.";
$_LANG['store']['siteBuilder']['featuresdescriptions']['store']['10'] = "Dostávejte okamžitá upozornění na objednávky e-mailem. Spravujte a prohlížejte přehled všech objednávek, vyhledávejte je, filtrujte podle kategorií, aktualizujte objednávky a údaje zákazníků a přidávejte sledovací čísla zásilek.";
$_LANG['store']['siteBuilder']['viewPricing'] = "Zobrazit ceny a balíčky";
$_LANG['store']['siteBuilder']['templatesTitle'] = "Šablony, které urychlí vaše podnikání";
$_LANG['store']['siteBuilder']['templatesOutro'] = "Pořiďte si Site Builder a prohlédněte si všech více než 150 šablon, se kterými rychle a snadno začnete.";
