$_LANG['store']['xoviNow']['faqTitle'] = "Často kladené dotazy";
$_LANG['store']['xoviNow']['faq1'] = "Co je SEO?";
$_LANG['store']['xoviNow']['faq1ans'] = "<p>SEO je zkratka pro Search Engine Optimization, tedy optimalizaci pro vyhledávače. Jde o zásadní strategii online marketingu, jejímž cílem je přivést na váš web potenciální zákazníky. Snaží se optimalizovat web tak, aby získal přední pozice pro vybraná klíčová slova ve vyhledávačích. Toho se dosahuje strategickým zlepšováním technického nastavení a obsahu webu a získáváním zpětných odkazů z jiných domén.</p><p>SEO se dělí do tří základních kategorií:</p><ol><li>Klíčová slova a pozice</li><li>On-page SEO</li><li>Off-page SEO</li></ol><p>Specialisté na SEO uplatňují opatření, která splňují hodnoticí faktory vyhledávačů v každé kategorii. Vyhledávače podle těchto faktorů určují, na jaké pozici web ve výsledcích vyhledávání zobrazí.</p>";
$_LANG['store']['xoviNow']['faq2'] = "Proč potřebuji SEO?";
$_LANG['store']['xoviNow']['faq2ans'] = "<p>Miliony lidí každý den používají vyhledávače k hledání informací a služeb ze všech oblastí života: recepty, návody, produkty, letenky, navigace, vstupenky, zábava a další. Většina lidí se na webu orientuje pomocí vyhledávačů, kde hledá odpovědi na své otázky a řešení svých problémů.</p><p>Studie ukazuje, že 68 % webového provozu pochází z vyhledávačů. 53 % tohoto provozu má původ v organickém vyhledávání – výsledcích, které nejsou reklamou (placené vyhledávání) a lze je zlepšit pomocí SEO.</p><img src=\":image1\"><p>Jinými slovy, organické vyhledávání (SEO) a placené vyhledávání (SEA, reklamy ve výsledcích vyhledávání) tvoří lví podíl provozu na webu.</p><p>I to, kam se vydáváme offline, výrazně ovlivňují vyhledávače: Google a Apple Mapy a místní výsledky vyhledávání používáme k hledání míst a služeb v okolí, jako jsou kadeřnictví, supermarkety, restaurace a lékaři. Cíl vybíráme podle online recenzí. A služby založené na vyhledávačích nás tam navigují – autem, veřejnou dopravou nebo pěšky.</p><p>Představte si, že vaše firma, produkty a služby nejsou ve výsledcích vyhledávání. Představte si, že vás lidé nemohou najít online, aby si koupili vaše produkty nebo našli cestu do vaší kamenné provozovny. Místo toho si nejspíš vyberou vaši konkurenci.</p>";
$_LANG['store']['xoviNow']['faq3'] = "Co pro mě může SEO udělat?";
$_LANG['store']['xoviNow']['faq3ans'] = "<p>Díky SEO mohou uživatelé najít vaši firmu, produkty a služby online – a koupit je. Jak už bylo řečeno, znamená to, že vás lidé snáze najdou online i offline.</p><p>SEO maximalizuje vaše šance na přední pozice pro klíčová slova zásadní pro vaše podnikání. Čím lepší pozice, tím více lidí najde cestu na váš web – ideálně na první stránce (neboli v první desítce) výsledků vyhledávání.</p><p><strong>Proč první stránka?</strong></p><p>Dobrá otázka. Studie ukázaly, že 31,7 % uživatelů klikne na první organický výsledek vyhledávání (první pozice); ohromujících 75,1 % všech kliknutí připadá na první tři výsledky. Poté počet kliknutí s každou další pozicí rychle klesá.</p><img src=\":image2\"><p>Toto chování ukazuje, že se uživatelé jen zřídka podívají na výsledky na druhé či další stránce, natož aby na ně klikli.</p><img src=\":image3\"><p>Proto musí být firmy přítomny na první stránce výsledků vyhledávání, alespoň pro relevantní klíčová slova.</p><p>Stručně řečeno: Pro freelancery a majitele firem je zásadní</p><ol><li>mít web nebo jakoukoli online prezentaci, i když své produkty či služby nabízejí offline</li><li>věnovat se SEO, aby se pro relevantní klíčová slova umístili na první stránce</li></ol>";
$_LANG['store']['xoviNow']['faq4'] = "Proč jsou klíčová slova důležitá?";
$_LANG['store']['xoviNow']['faq4ans'] = "<p><em>Klíčové slovo</em> je odborný výraz pro vyhledávací dotazy (slova, fráze, věty a otázky). Jejich pomocí uživatelé hledají obsah, který odpovídá na jejich otázky a nabízí řešení. Zjednodušeně řečeno je klíčové slovo spojnicí mezi uživateli a vaším webem. Vyhledávače porovnávají klíčová slova s weby a hledají obsah s nejvyšší relevancí.</p><p>Velkou část SEO tvoří vyhledání klíčových slov, která mají potenciál přivést na váš web relevantní návštěvnost – jinými slovy potenciální zákazníky. K tomu je potřeba zjistit, jaké výrazy (klíčová slova) lidé používají při hledání nabídek jako je ta vaše. Tento proces se nazývá analýza klíčových slov. V ideálním případě vám analýza klíčových slov poskytne seznam klíčových slov pokrývajících vyhledávací dotazy v celé zákaznické cestě.</p>";
$_LANG['store']['xoviNow']['faq5'] = "Co je optimalizace klíčových slov?";
$_LANG['store']['xoviNow']['faq5ans'] = "<p>Víme tedy, že relevance je zásadním faktorem pro přední pozici ve výsledcích vyhledávání. Abyste vytvořili relevantní obsah, měli byste témata a otázky kolem klíčového slova zpracovat na samostatné podstránce či URL. Poté zajistěte, aby se klíčové slovo objevilo na důležitých místech stránky.</p><p>Řekněme, že podnikáte se zmrzlinou. Jedním z vašich klíčových slov je <em>zmrzlinový sendvič s karamelem</em>. Soustředíte se tedy na vše, co souvisí se <em>zmrzlinovým sendvičem s karamelem</em>.</p><p>Vytvoříte stránku s receptem na <em>zmrzlinový sendvič s karamelem</em>, kde uživatelé najdou snadno srozumitelný recept, fotografie nebo videa a odpovědi na případné otázky. <em>Zmrzlinový sendvič s karamelem</em> je vaše hlavní klíčové slovo, které by se mělo objevit v URL stránky, titulku, nadpisech a dalších místech.</p><p>Samostatná stránka optimalizovaná na klíčové slovo umožní vyhledávačům – i uživatelům – snadno pochopit, o čem stránka je. Díky tomu ji mohou zobrazit na dobrých pozicích v souvisejících výsledcích vyhledávání.</p>";
$_LANG['store']['xoviNow']['faq6'] = "Jak používat poradce";
$_LANG['store']['xoviNow']['faq6ans'] = "<p>Nejprve si prohlédněte nástěnku poradce kliknutím na Poradce v horní navigační liště. Jde o kanbanovou nástěnku, která vám pomáhá třídit úkoly podle stavu. Úkoly jsou barevně odlišeny podle důležitosti:</p><ul><li><strong>Červená:</strong> Vysoká. Vyřešte co nejdříve.</li><li><strong>Žlutá:</strong> Střední. Pusťte se do nich brzy.</li><li><strong>Modrá:</strong> Nízká. Mějte je na paměti a vyřešte je, až budete moci.</li></ul><img src=\":image1\"><p>Dokončené úkoly můžete přetahovat, přiřazovat je dalším uživatelům (v závislosti na plánu) a filtrovat podle řešitele.</p><p>Jak bylo uvedeno výše, úkoly jsou kombinací standardních základních SEO opatření a problémů zjištěných při týdenních automatických auditech vašeho webu.</p>";
$_LANG['store']['xoviNow']['faq7'] = "Chci poradce i pro další weby. Jak ho získám?";
$_LANG['store']['xoviNow']['faq7ans'] = "<p>Mějte na paměti, že funkce Poradce vyžaduje <em>projekt</em>. Většina úkolů poradce je navíc přizpůsobena webu daného projektu (obvykle vašemu nebo webu klienta). Pokud spravujete více webů, musíte pro každý z nich vytvořit samostatný projekt.</p><p>Pro přidání nebo přepnutí na jiný projekt klikněte na nabídku <em>Projekty</em> v horní navigační liště. V závislosti na plánu může být pro přidání dalšího projektu nutný upgrade.</p>";
$_LANG['store']['xoviNow']['faq8'] = "Jak přiřadím úkoly dalším uživatelům?";
$_LANG['store']['xoviNow']['faq8ans'] = "<p>Pro přiřazení úkolu dalším uživatelům potřebujete plán, který umožňuje další uživatele. Pokud jej váš plán zahrnuje, najdete v poradci a v úkolech nabídku Řešitel. Stačí zvolit uživatele, kterému chcete úkol přiřadit nebo podle kterého chcete poradce filtrovat. Nového uživatele přidáte kliknutím na svůj profilový avatar a poté na <em>Uživatelé</em>. Pokud váš plán další uživatele nezahrnuje, nabídku <em>Řešitel</em> v poradci ani v úkolech neuvidíte. Pro přidání uživatelů přejděte na vyšší plán.</p>";
$_LANG['store']['xoviNow']['faq9'] = "Zobrazují se mi úkoly, které už mám hotové. Proč?";
$_LANG['store']['xoviNow']['faq9ans'] = "<p>Existují dva důvody, proč můžete vidět úkoly, které jste již vyřešili. Jak bylo uvedeno výše, úkoly jsou kombinací základních SEO opatření a problémů zjištěných při týdenních automatických auditech vašeho webu.</p><p>Zaprvé, úkoly se základními SEO opatřeními jsou pro všechny stejné a nejsou přizpůsobeny vašemu webu ani podnikání. Nevíme například, zda jste pro svou firmu vytvořili účet Google a nastavili Search Console nebo zda jste nainstalovali SEO pluginy. Pokud ano – skvělá práce! Stačí tyto úkoly označit jako Hotovo.</p><p>Druhým důvodem je, že se poradce automaticky aktualizuje na základě výsledků automatických týdenních auditů webu. Jinými slovy, pokud audit webu zjistí problém týkající se úkolu, který jste v minulosti dokončili, úkol se automaticky aktualizuje a znovu se objeví v sekci Otevřené.</p>";
$_LANG['store']['xoviNow']['faq10'] = "Co je viditelnost projektu?";
$_LANG['store']['xoviNow']['faq10ans'] = "<p>Možná vás už napadlo: „Moment, ale moje viditelnost pro klíčová slova, která s mým podnikáním nesouvisejí, mě nezajímá.“ A máte pravdu. Viditelnost je sice skvělé skóre pro získání představy o celkovém výkonu a obecné porovnání webů, ale není přizpůsobena vaší konkrétní sadě klíčových slov.</p><p>Proto nabízíme <em>viditelnost projektu</em>. Tato metrika se počítá stejně jako viditelnost, ale místo 500 000 klíčových slov napříč obory vychází výhradně z klíčových slov ve vašem Rank Trackeru.</p><p>Jinými slovy, viditelnost projektu je vlastní skóre viditelnosti pro jedinečnou sadu klíčových slov relevantních pro vaše podnikání.</p><p>Viditelnost projektu najdete zde: <em>Projekty → Rank Tracker → Viditelnost</em>.</p><p>Jak možná víte, v Rank Trackeru můžete sledovat i pozice svých konkurentů. Získáte tak viditelnost projektu i pro ně, což umožňuje mnohem realističtější srovnání. I když mají mírně odlišné portfolio produktů či služeb, viditelnost projektu zohledňuje výhradně klíčová slova, která skutečně sdílíte.</p>";
$_LANG['store']['xoviNow']['faq11'] = "Proč je skóre viditelnosti užitečné?";
$_LANG['store']['xoviNow']['faq11ans'] = "<p>Use your Visibility score as an indicator of your overall SEO performance, problems, and potential for optimization.</p><p><strong>1. Get An Idea of Your Overall SEO Performance</strong></p><p>You can track rankings for single keywords and know which position you rank on. It's an important thing to do. However, rank tracking does not give you a bird's eye view perspective of the overall improvement of your rankings—but Visibility does. When your SEO measures are effective and rankings improve, so does your Visibility score.</p><p><strong>2. Diagnose SEO Problems</strong></p><p>A sudden drop in your Visibility indicates problems in your SEO performance. Use Visibility like an alert. If it drops significantly, start digging for what happened. Here's a list of common reasons:</p><ul><li>You were hit with a <strong>Google Penalty</strong>. Check Search Console for notifications. Make sure to follow <a href=\":googleWebmasterGuidelinesUrl\" target=\"_blank\">Google's Webmaster Guidelines</a>.</li><li>There are ramifications from a recent change in Google's algorithm. Inquire about recent <strong>Google Updates</strong> and what they entail.</li><li>Your competitors optimized their websites and content, and now they out-compete you. Compare their (historical) <strong>Visibility</strong> with yours. Use the <a href=\":waybackMachineUrl\" target=\"_blank\">Wayback Machine</a> to compare how their content changed.</li><li>You relaunched your site without SEO in mind. For example, check <em>robots.txt</em> and <em>.htaccess</em> for accidentally blocked pages, increased 404 status codes, faulty 301-redirects, and internal links.<br><br>You changed your content in a way that didn't help your rankings. Consider reversing the changes.<br><br>Your website has technical issues. Run a <em>Site Audit</em> or check your <strong><em>Advisor</em></strong> for open technical tasks. Check your backend for outdated, recently updated, or incompatible <strong>plugins</strong> that may cause havoc.<br><br>Hosting issues are the cause. Inquire whether your host made recent changes, has been hacked, moved their servers, or experienced technical difficulties. See if your server has issues.</li></ul><p>Keep in mind that this list is not exhaustive. One or more of those reasons can apply simultaneously, or there could be other reasons altogether.</p><p><strong>3. Competitor Comparison</strong></p><p>Visibility is a great metric for a quick comparison of two or more websites. Check your Visibility against theirs. Who is out-competing who? Has a competitor outperformed you in the past or vice versa? Who's leading the field, and how big is the gap between you and your fiercest competitor? Answering those questions will help you develop an SEO strategy to come out (and stay) at the top of your niche.</p><p><strong>4. Track Visibility Development Over Time With Historical Data</strong></p><p>Want to know how a website fared over time? We provide historical data going all the way back to 2009, free of seasonal fluctuations. That way, you can track and compare historic Visibility and see their development over long periods of time.</p>";
$_LANG['store']['xoviNow']['faq12'] = "Jak mohu zlepšit své skóre viditelnosti?";
$_LANG['store']['xoviNow']['faq12ans'] = "<p>Krátká odpověď: Nedělejte ze zlepšení viditelnosti cíl své SEO strategie.</p><p>Dlouhá odpověď: Viditelnost <em>odráží</em> kvalitu vašich pozic v jediné metrice; sama k lepším pozicím nevede. Stanovte si za cíl zlepšit pozice pro relevantní klíčová slova, která potenciální zákazníci skutečně používají při hledání produktů a služeb jako ty vaše. Zlepšením pozic se zlepší i viditelnost. Skutečně ale záleží na pozicích.</p><p>Obecně platí, že vaše skóre viditelnosti bude vyšší, pokud</p><ul><li>URL adresy vaší domény mají dobré pozice</li><li>máte velký počet indexovaných URL s dobrými pozicemi</li><li>máte dobré pozice pro klíčová slova s vysokým objemem vyhledávání</li></ul>";
